import os, hashlib

# TOY demo of envelope encryption. XOR keystream stands in for AES-GCM;
# never use this for real data.
def stream(key, n):
    out, i = b"", 0
    while len(out) < n:
        out += hashlib.sha256(key + bytes([i])).digest()
        i += 1
    return out[:n]

def xor(key, data):
    return bytes(a ^ b for a, b in zip(data, stream(key, len(data))))

master = os.urandom(32)          # lives only inside "KMS", never leaves

def generate_data_key():
    dk = os.urandom(32)
    return dk, xor(master, dk)   # plaintext key + copy wrapped by master

def kms_decrypt(wrapped):
    return xor(master, wrapped)

data = b"card=4111-0000 amount=42"
dk, wrapped = generate_data_key()
blob = (xor(dk, data), wrapped)  # store ciphertext + wrapped key together
del dk                           # discard the plaintext data key

print("plain     :", data)
print("ciphertext:", blob[0].hex())
back = xor(kms_decrypt(blob[1]), blob[0])  # one small KMS call to unwrap
print("decrypted :", back)
print("match     :", back == data)

# A request must pass every layer: SCP, boundary, identity policy.
def evaluate(action, scp, boundary, identity, explicit_deny=()):
    if action in explicit_deny:
        return "DENY (explicit)"
    for name, layer in (("SCP", scp), ("boundary", boundary), ("identity", identity)):
        if action not in layer:
            return "DENY (not allowed by " + name + ")"
    return "ALLOW"

scp = {"s3:GetObject", "s3:PutObject", "ec2:RunInstances"}   # org cap
boundary = {"s3:GetObject", "s3:PutObject", "iam:CreateUser"}  # per-role cap
identity = {"s3:GetObject", "s3:DeleteObject", "iam:CreateUser"}  # grants

for a in ["s3:GetObject", "s3:PutObject", "s3:DeleteObject", "iam:CreateUser"]:
    print(a, "->", evaluate(a, scp, boundary, identity))
print("effective:", sorted(scp & boundary & identity))
